def apply_d2_ridge_stacker(rank_arm1, rank_arm2):
    """
    Args:
        rank_arm1: array of shape (N, 12), percentile ranks of Model A (0..1)
        rank_arm2: array of shape (N, 12), percentile ranks of Model B (0..1)
    Returns:
        fused_preds: array of shape (N, 12)
    """
    X_24 = np.hstack([rank_arm1, rank_arm2])
    # Linear projection: (N, 24) x (24, 12) + (12,)
    fused = np.dot(X_24, D2_RIDGE_WEIGHTS.T) + D2_RIDGE_INTERCEPTS
    return fused
